/**
 * Writes docs/CATALYST_TABLES.md: the exact tables and columns to create in the
 * Catalyst Data Store console, generated from src/database/catalyst/schema.js.
 *
 *   node scripts/catalyst/print-schema.js
 */

const fs = require('fs');
const path = require('path');
const { buildSpec } = require('../../src/database/catalyst/schema');

const TYPE_LABEL = { varchar: 'Var Char', text: 'Text', int: 'Int', bigint: 'BigInt', boolean: 'Boolean' };

const { tables, limits } = buildSpec();
const lines = [
  '# Catalyst Data Store tables for BhoomiScan',
  '',
  'Generated by `node scripts/catalyst/print-schema.js` from `src/database/catalyst/schema.js`; do not edit by hand.',
  '',
  `Create these ${tables.length} tables in the Catalyst console (Cloud Scale → Data Store), Development environment first.`,
  'Catalyst adds `ROWID`, `CREATORID`, `CREATEDTIME` and `MODIFIEDTIME` to every table automatically; the app does not use them.',
  '',
  '| Rule | Why |',
  '|---|---|',
  '| `id` is our UUID (Var Char, unique, mandatory) | URLs and API responses keep their current ids; Catalyst\'s own `ROWID` is not used for references |',
  '| Columns ending in `_id` hold the related row\'s UUID | Catalyst foreign keys point at `ROWID`, so relations are checked by the app |',
  '| `*_at` / dates are **BigInt** epoch milliseconds (UTC) | Catalyst DateTime has no milliseconds or time zone |',
  `| JSON and arrays are **Text** (max ${limits.TEXT_MAX} characters) | Catalyst has no JSON type |`,
  '| `*_uq` columns are unique combined keys | Catalyst supports single-column unique only |',
  '',
];
for (const table of tables) {
  lines.push(`## ${table.table}`, '', '| Column | Type | Max length | Mandatory | Unique | Notes |', '|---|---|---|---|---|---|');
  for (const column of table.columns) {
    const max = column.type === 'varchar' ? column.maxLength : column.type === 'text' ? limits.TEXT_MAX : '';
    lines.push(`| \`${column.name}\` | ${TYPE_LABEL[column.type]} | ${max} | ${column.mandatory ? 'yes' : ''} | ${column.unique ? 'yes' : ''} | ${column.note || ''} |`);
  }
  lines.push('');
}
const out = path.join(__dirname, '..', '..', 'docs', 'CATALYST_TABLES.md');
fs.writeFileSync(out, `${lines.join('\n')}`);
console.log(`Wrote ${path.relative(process.cwd(), out)}: ${tables.length} tables, ${tables.reduce((n, t) => n + t.columns.length, 0)} columns`);
